         await markNotificationEmailSkipped(db, {
           id: notification.id,
           reason: "Recipient email unavailable",
         });
         return;
       }

       try {
         const delivery = await sendEmailViaResend(resendApiKey, resendFromEmail, {
           to: owner.email,
