   interview_in_progress: {
     badge: "Interview in Progress",
     tone: "bg-amber-500/10 text-amber-700 dark:text-amber-300",
     blurb: "Your RoundZero interview is in progress",
   },
   under_review: {
-    badge: "Under Review",
