 const stripToolLeakText = (value: string) => {
   const trimmed = value.trim();
   if (!trimmed.startsWith("{")) {
     return value;
   }

   try {
     const parsed = JSON.parse(trimmed) as {
       type?: unknown;
       name?: unknown;
       parameters?: unknown;
     };

     if (
       parsed.type === "function" &&
       typeof parsed.name === "string" &&
       Object.hasOwn(parsed, "parameters")
     ) {
       return "";
     }
   } catch {
     return value;
   }

   return value;
