       if (
         typeof parsed === "object" &&
         parsed !== null &&
         "overall" in (parsed as Record<string, unknown>)
       ) {
         const score = (parsed as Record<string, unknown>).overall;
         return typeof score === "number" && Number.isFinite(score) ? score : null;
       }
