+}
+
+export const getApplicationFollowupForCandidateQuery = `-- name: getApplicationFollowupForCandidate :one
+SELECT af.id,
+       af.application_id,
+       af.questions,
+       af.answers,
+       af.status,
+       af.due_at,
+       af.submitted_at,
+       af.created_at,
+       af.updated_at,
+       a.candidate_id,
+       a.job_id,
