+                  <HugeiconsIcon icon={ArrowRight01Icon} strokeWidth={2} className="size-4" />
+                </Button>
+              ) : (
+                <Button type="submit" disabled={submitMutation.isPending}>
+                  {submitMutation.isPending ? "Submitting..." : "Submit answers"}
+                </Button>
+              )}
+            </div>
+          </form>
+        </CardContent>
+      </Card>
+    </div>
+  );
+}

