+import { Sql } from "postgres";
+
+export const upsertApplicationFollowupQuery = `-- name: upsertApplicationFollowup :one
+INSERT INTO application_followups (
+  application_id,
+  questions,
+  answers,
+  status,
+  due_at,
+  submitted_at
+)
+VALUES ($1, $2, $3, $4, $5, $6)
+ON CONFLICT (application_id) DO UPDATE
